const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
const unitOf = currency => ZERO_DECIMAL.includes(currency) ? 1 : THREE_DECIMAL.includes(currency) ? 1000 : 100;
const day = ts => new Date(ts * 1000).toISOString().slice(0, 10);
const STRIPE_VERSION = '2026-08-26.dahlia';
const wrongVersion = ev => ev.payload.api_version !== STRIPE_VERSION &&
  `PERMANENT: event is in Stripe API version ${ev.payload.api_version}; pin the webhook endpoint to ${STRIPE_VERSION}`;

// map each paid Stripe invoice to Xero documents. events that can't or needn't be posted get their outcome
// here, the rest go contacts -> invoices -> payments, each step checks Xero before creating anything
const { settings: s, links } = $('Load context').first().json.ctx;
const cur = s.xero_currency;
const unit = unitOf(cur);
const sum = xs => xs.reduce((a, b) => a + b, 0);
const outcomes = [];   // {event_id, error | note}, decided without Xero
const invoices = {};   // Stripe invoice id -> Xero invoice and payment to post, and the events asking for it
const customers = {};  // Stripe customer id -> Xero contact to find or create

for (const { json: ev } of $('Events').all()) {
  const inv = ev.payload.data.object;
  const currency = String(inv.currency).toUpperCase();
  const settle = outcome => outcomes.push({ event_id: ev.id, ...outcome });
  if (invoices[inv.id]) { invoices[inv.id].events.push(ev.id); continue; }  // two events for one invoice
  if (links[inv.id]?.payment) { settle({ note: 'already in Xero' }); continue; }
  if (wrongVersion(ev)) { settle({ error: wrongVersion(ev) }); continue; }
  if (inv.total === 0) { settle({ note: 'zero-amount invoice, nothing to post' }); continue; }
  if (currency !== cur) { settle({ error: `PERMANENT: currency ${currency} is not the Xero organisation's ${cur}` }); continue; }
  if ((inv.total_taxes ?? []).some(t => t.amount)) { settle({ error: 'PERMANENT: invoice has tax; posting it without tax would misstate it' }); continue; }
  if (inv.amount_paid !== inv.total) { settle({ error: `PERMANENT: paid partly from customer balance or credit (${inv.amount_paid} of ${inv.total})` }); continue; }

  // line detail if the event has every line and they add up, otherwise one line with the exact total
  const lines = (inv.lines?.data ?? []).map(l => ({
    description: l.description || 'Stripe line item',
    net: l.amount - sum((l.discount_amounts ?? []).map(d => d.amount)),
  }));
  const exact = !inv.lines?.has_more && lines.length > 0 && sum(lines.map(l => l.net)) === inv.total;
  const posted = exact ? lines : [{ description: `Stripe invoice ${inv.number}`, net: inv.total }];

  // contact names carry the customer id, so two John Smiths in Stripe stay two contacts in Xero
  const base = (inv.customer_name || inv.customer_email || '').trim();
  let name = base ? `${base} (${inv.customer})` : inv.customer;
  if (name.length > 255) name = `${base.slice(0, 255 - inv.customer.length - 4)}… (${inv.customer})`;
  customers[inv.customer] ??= { Name: name, ContactNumber: inv.customer, ...(inv.customer_email ? { EmailAddress: inv.customer_email } : {}) };

  invoices[inv.id] = {
    events: [ev.id],
    customer: inv.customer,
    amount: inv.amount_paid / unit,
    invoice: {
      Type: 'ACCREC', InvoiceNumber: inv.number ?? inv.id, Reference: inv.id, Status: 'AUTHORISED', CurrencyCode: cur,
      Date: day(inv.effective_at ?? inv.created), DueDate: day(inv.due_date ?? inv.effective_at ?? inv.created),
      LineAmountTypes: 'NoTax', Url: inv.hosted_invoice_url ?? undefined,
      LineItems: posted.map(l => ({ Description: l.description, Quantity: 1, UnitAmount: l.net / unit, AccountCode: s.xero_sales_account })),
    },
    payment: {
      Account: { Code: s.xero_bank_account }, Amount: inv.amount_paid / unit, Reference: inv.id,
      Date: day(inv.status_transitions?.paid_at ?? inv.created),
    },
  };
}

// contacts linked on earlier runs are known, ask Xero about the rest by customer id
const known = {};
for (const c of Object.keys(customers)) if (links[c]?.contact) known[c] = links[c].contact;
const unknown = Object.keys(customers).filter(c => !known[c]);
const where = unknown.map(c => `ContactNumber=="${c}"`).join(' OR ');
return [{ json: {
  ...(unknown.length ? { service: 'xero', method: 'GET', url: `${s.xero_api_base}/Contacts?where=${encodeURIComponent(where)}` } : { skip: true }),
  plan: { settings: s, outcomes, invoices, customers, known },
} }];

// contacts linked before or found in Xero just now. returns Stripe customer id -> Xero ContactID
const contactIds = () => {
  const { known } = $('Plan').first().json.plan;
  const ids = { ...known };
  for (const node of ['Xero: find contacts', 'Xero: create contacts']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.Contacts ?? []) if (c.ContactNumber && c.StatusAttributeString !== 'ERROR') ids[c.ContactNumber] = c.ContactID;
  }
  return ids;
};

const { plan } = $('Plan').first().json;
const have = contactIds();
const missing = Object.values(plan.customers).filter(c => !have[c.ContactNumber]);
return [{ json: missing.length
  ? { service: 'xero', method: 'PUT', url: `${plan.settings.xero_api_base}/Contacts?summarizeErrors=false`, body: { Contacts: missing } }
  : { skip: true } }];

// any invoice still to pay may already be in Xero from an attempt that died halfway, look up by number
const { plan } = $('Plan').first().json;
const numbers = Object.values(plan.invoices).map(i => encodeURIComponent(i.invoice.InvoiceNumber));
return [{ json: numbers.length
  ? { service: 'xero', method: 'GET', url: `${plan.settings.xero_api_base}/Invoices?InvoiceNumbers=${numbers.join(',')}` }
  : { skip: true } }];

// contacts linked before or found in Xero just now. returns Stripe customer id -> Xero ContactID
const contactIds = () => {
  const { known } = $('Plan').first().json.plan;
  const ids = { ...known };
  for (const node of ['Xero: find contacts', 'Xero: create contacts']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.Contacts ?? []) if (c.ContactNumber && c.StatusAttributeString !== 'ERROR') ids[c.ContactNumber] = c.ContactID;
  }
  return ids;
};

// Xero invoices found or created, by number
const xeroInvoices = () => {
  const byNumber = {};
  for (const node of ['Xero: find invoices', 'Xero: create invoices']) {
    if (!$(node).isExecuted) continue;
    for (const i of $(node).first().json.Invoices ?? []) if (i.StatusAttributeString !== 'ERROR') byNumber[i.InvoiceNumber] = i;
  }
  return byNumber;
};

// create what Xero lacks, for customers that have a contact now. Contact gets only the id, more fields
// would update the contact
const { plan } = $('Plan').first().json;
const contacts = contactIds();
const found = xeroInvoices();
const create = Object.values(plan.invoices)
  .filter(p => !found[p.invoice.InvoiceNumber] && contacts[p.customer])
  .map(p => ({ ...p.invoice, Contact: { ContactID: contacts[p.customer] } }));
return [{ json: create.length
  ? { service: 'xero', method: 'PUT', url: `${plan.settings.xero_api_base}/Invoices?summarizeErrors=false`, body: { Invoices: create } }
  : { skip: true } }];

// Xero invoices found or created, by number
const xeroInvoices = () => {
  const byNumber = {};
  for (const node of ['Xero: find invoices', 'Xero: create invoices']) {
    if (!$(node).isExecuted) continue;
    for (const i of $(node).first().json.Invoices ?? []) if (i.StatusAttributeString !== 'ERROR') byNumber[i.InvoiceNumber] = i;
  }
  return byNumber;
};

// pay each invoice that still has exactly the Stripe amount due. already paid means an earlier attempt did it
const { plan } = $('Plan').first().json;
const invoices = xeroInvoices();
const pay = [];
for (const [stripeId, p] of Object.entries(plan.invoices)) {
  const x = invoices[p.invoice.InvoiceNumber];
  if (x && x.Reference === stripeId && x.Status === 'AUTHORISED' && Math.abs(x.AmountDue - p.amount) < 0.0005) {
    pay.push({ ...p.payment, Invoice: { InvoiceID: x.InvoiceID } });
  }
}
return [{ json: pay.length
  ? { service: 'xero', method: 'PUT', url: `${plan.settings.xero_api_base}/Payments?summarizeErrors=false`, body: { Payments: pay } }
  : { skip: true } }];

const problems = el => (el.ValidationErrors ?? []).map(e => e.Message).join('; ') || 'rejected by Xero';
const ok = el => el.StatusAttributeString !== 'ERROR';
// contacts linked before or found in Xero just now. returns Stripe customer id -> Xero ContactID
const contactIds = () => {
  const { known } = $('Plan').first().json.plan;
  const ids = { ...known };
  for (const node of ['Xero: find contacts', 'Xero: create contacts']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.Contacts ?? []) if (c.ContactNumber && c.StatusAttributeString !== 'ERROR') ids[c.ContactNumber] = c.ContactID;
  }
  return ids;
};
// Xero invoices found or created, by number
const xeroInvoices = () => {
  const byNumber = {};
  for (const node of ['Xero: find invoices', 'Xero: create invoices']) {
    if (!$(node).isExecuted) continue;
    for (const i of $(node).first().json.Invoices ?? []) if (i.StatusAttributeString !== 'ERROR') byNumber[i.InvoiceNumber] = i;
  }
  return byNumber;
};

// one outcome per event, plus the Stripe -> Xero links worth keeping
const { plan } = $('Plan').first().json;
const contacts = contactIds(), invoices = xeroInvoices();
const failed = { contact: {}, invoice: {}, payment: {} }, paid = {};
for (const c of $('Xero: create contacts').first().json.Contacts ?? []) if (!ok(c)) failed.contact[c.ContactNumber] = problems(c);
for (const i of $('Xero: create invoices').first().json.Invoices ?? []) if (!ok(i)) failed.invoice[i.InvoiceNumber] = problems(i);
for (const p of $('Xero: record payments').first().json.Payments ?? []) {
  if (ok(p)) paid[p.Invoice.InvoiceID] = p; else failed.payment[p.Invoice.InvoiceID] = problems(p);
}

const links = Object.entries(contacts).filter(([cus]) => !plan.known[cus]).map(([cus, id]) => ({ stripe_id: cus, kind: 'contact', xero_id: id }));
const results = [...plan.outcomes];
for (const [stripeId, p] of Object.entries(plan.invoices)) {
  const x = invoices[p.invoice.InvoiceNumber];
  let error = null;
  if (!contacts[p.customer]) error = `Xero contact: ${failed.contact[p.customer] ?? 'not found and not created'}`;
  else if (!x) error = `Xero invoice: ${failed.invoice[p.invoice.InvoiceNumber] ?? 'not found and not created'}`;
  else if (x.Reference !== stripeId) error = `PERMANENT: Xero invoice ${x.InvoiceNumber} has Reference "${x.Reference}", not ${stripeId}; the number is taken`;
  else if (paid[x.InvoiceID] || x.AmountDue === 0) {
    links.push({ stripe_id: stripeId, kind: 'invoice', xero_id: x.InvoiceID, amount: x.Total });
    const paymentId = paid[x.InvoiceID]?.PaymentID ?? x.Payments?.[0]?.PaymentID;
    if (paymentId) links.push({ stripe_id: stripeId, kind: 'payment', xero_id: paymentId, amount: p.amount });
  } else if (failed.payment[x.InvoiceID]) error = `Xero payment: ${failed.payment[x.InvoiceID]}`;
  else error = `PERMANENT: Xero invoice ${x.InvoiceNumber} is ${x.Status} with ${x.AmountDue} due, Stripe paid ${p.amount}`;
  for (const event_id of p.events) results.push({ event_id, error });
}
return [{ json: { links, results } }];
